# frozen_string_literal: true

require "rails_helper"

# Declared outside RSpec.describe, not as a `def` inside one: Steep resolves
# neither (see spec/lib/sway/settings_spec.rb's SettingsSpecHelpers for the
# same reasoning, and sig-test/lib/sway/subprocess_spec.rbs for the
# precedent).
module SettingsSignaturesSpecHelpers
  # Strips the "generated by / do not hand-edit" header comment every
  # committed file carries -- to_rbs never emits it -- then collapses blank
  # lines and trailing whitespace, so the comparison is about the shape of
  # the signature rather than incidental formatting.
  def self.normalize(text)
    text.lines
      .reject { |line| line.lstrip.start_with?("#") }
      .map(&:rstrip)
      .reject(&:empty?)
      .join("\n")
  end
end

# @lat: [[settings-group-declaration-notes#Why settings_signatures_spec.rb exists, and why it is not a Steep check]]
RSpec.describe "settings signatures" do
  Sway::Settings::GROUPS.each do |name, klass|
    describe "#{klass} (registered as #{name.inspect})" do
      it "matches its committed signature file, or names the file and the command to regenerate it" do
        path = Rails.root.join("sig/lib/sway/settings/#{name}.rbs")

        # Fails rather than skips a missing file -- a skip on a missing file
        # is the same as no check at all for a group somebody forgot to
        # commit.
        expect(File.file?(path)).to be(true),
          "#{path} does not exist -- run `bin/rails runner 'puts #{klass}.to_rbs'` " \
          "and commit the output to #{path}"

        committed = SettingsSignaturesSpecHelpers.normalize(File.read(path))
        generated = SettingsSignaturesSpecHelpers.normalize(klass.to_rbs)

        # No diff printed on purpose: an RBS diff is unreadable in a CI log,
        # and a reader who sees the file name and the regeneration command
        # does not need one.
        expect(committed).to eq(generated),
          "#{path} no longer matches #{klass}.to_rbs -- regenerate it with " \
          "`bin/rails runner 'puts #{klass}.to_rbs'` and commit the result"
      end
    end
  end
end
